import{_ as a,H as i,f as n,i as p}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"02-如何将容器镜像部署到K8s？","description":"","frontmatter":{},"headers":[{"level":2,"title":"安装 Kubernetes","slug":"安装-kubernetes","link":"#安装-kubernetes","children":[]},{"level":2,"title":"初识 Kubernetes","slug":"初识-kubernetes","link":"#初识-kubernetes","children":[{"level":3,"title":"部署容器镜像到 K8s","slug":"部署容器镜像到-k8s","link":"#部署容器镜像到-k8s","children":[]},{"level":3,"title":"查看和访问 Pod","slug":"查看和访问-pod","link":"#查看和访问-pod","children":[]},{"level":3,"title":"业务进程、容器镜像和工作负载之间的关系","slug":"业务进程、容器镜像和工作负载之间的关系","link":"#业务进程、容器镜像和工作负载之间的关系","children":[]}]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"云原生架构与GitOps实战/02-如何将容器镜像部署到K8s？.md","filePath":"云原生架构与GitOps实战/02-如何将容器镜像部署到K8s？.md","lastUpdated":1795538134000}'),e={name:"云原生架构与GitOps实战/02-如何将容器镜像部署到K8s？.md"};function l(t,s,h,o,k,d){return i(),n("div",null,[...s[0]||(s[0]=[p(`<h1 id="_02-如何将容器镜像部署到k8s" tabindex="-1">02-如何将容器镜像部署到K8s？ <a class="header-anchor" href="#_02-如何将容器镜像部署到k8s" aria-label="Permalink to &quot;02-如何将容器镜像部署到K8s？&quot;">​</a></h1><p>你好，我是王炜。</p><p>上节课，我们学习了容器镜像的概念以及如何将业务构建成容器镜像。容器镜像是我们学习云原生的起点，同时也会贯穿在云原生的各个环节之中，希望你能多花点时间巩固。这节课，我们一起来看看如何将容器镜像部署到 K8s。</p><p>K8s 的系统设计非常复杂，这导致它的学习曲线非常陡峭。尤其是对于刚入门的同学而言，面对繁杂的概念时往往会不知所措，也无从下手。再加上学习过程缺乏实战性的反馈，很容易导致“从入门到放弃”的情况出现。</p><p>所以这节课，我打算摒弃概念先行的教学方法，从实战的角度出发，带你从零入门 K8s。</p><p>我会继续延伸上一节课程的内容，带你把之前构建的容器镜像部署到 K8s 集群中。在实战的过程中，我也会讲解 K8s 的一些基本概念。</p><p>在开始实践之前，你需要做好以下准备：</p><ul><li><p>准备一台电脑（首选 Linux 或 macOS，Windows 也适用，需要稍微注意一下操作上的差异）；</p></li><li><p>安装 Docker；</p></li><li><p>安装 Kubectl。</p></li></ul><h2 id="安装-kubernetes" tabindex="-1">安装 Kubernetes <a class="header-anchor" href="#安装-kubernetes" aria-label="Permalink to &quot;安装 Kubernetes&quot;">​</a></h2><p>如何获得一个 K8s 集群是每一个开发者需要熟练掌握的内容。</p><p>安装 K8s 的方法非常多，有生产级的安装方法，也有以测试为目标的安装方法。为了方便测试，这里我推荐一种在本地安装 K8s 集群的办法：Kind。</p><p>首先，你需要根据官方步骤安装 Kind，它是一个命令行工具，使用非常简单。</p><p>接下来，我们开始创建 K8s。</p><p>将以下内容保存为 config.yaml：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kind: Cluster</span></span>
<span class="line"><span>apiVersion: kind.x-k8s.io/v1alpha4</span></span>
<span class="line"><span>nodes:</span></span>
<span class="line"><span>- role: control-plane</span></span>
<span class="line"><span> kubeadmConfigPatches:</span></span>
<span class="line"><span> - |</span></span>
<span class="line"><span>   kind: InitConfiguration</span></span>
<span class="line"><span>   nodeRegistration:</span></span>
<span class="line"><span>     kubeletExtraArgs:</span></span>
<span class="line"><span>       node-labels: &quot;ingress-ready=true&quot;</span></span>
<span class="line"><span> extraPortMappings:</span></span>
<span class="line"><span> - containerPort: 80</span></span>
<span class="line"><span>   hostPort: 80</span></span>
<span class="line"><span>   protocol: TCP</span></span>
<span class="line"><span> - containerPort: 443</span></span>
<span class="line"><span>   hostPort: 443</span></span>
<span class="line"><span>   protocol: TCP</span></span></code></pre></div><p>执行 kind create 命令，创建 K8s 集群：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">❯</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kind</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cluster</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config.yaml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Creating</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cluster</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;kind&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">✓</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Ensuring</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> image</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (kindest/node:v1.23.4)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">✓</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Preparing</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nodes</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 📦</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">✓</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Writing</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> configuration</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 📜</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">✓</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Starting</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> control-plane</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 🕹️</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">✓</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Installing</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CNI</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 🔌</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">✓</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Installing</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> StorageClass</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 💾</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> context</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;kind-kind&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">You</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> can</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> use</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cluster</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> with:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cluster-info</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --context</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kind-kind</span></span></code></pre></div><p>通过这两个简单的步骤，我们的本地 K8s 集群就创建好了。</p><h2 id="初识-kubernetes" tabindex="-1">初识 Kubernetes <a class="header-anchor" href="#初识-kubernetes" aria-label="Permalink to &quot;初识 Kubernetes&quot;">​</a></h2><p>K8s 的概念既多又复杂，如果像教科书一样把这些概念一条一条给你讲出来，最后你可能也记不住。所以，我也不打算这么做。</p><p>我想先问你一个问题：Docker 已经挺好用了，我们为什么还需要 K8s 呢？你可以试着用 30秒来思考一下。</p><p>我用一个场景来给你解释一下。还记得我们在上节课提到的启动一个容器的方法吗？这条命令非常简单，只需要运行 docker run 就可以了。</p><p>但是试想一下，如果你需要同时启动 10 个不同的容器镜像，是不是需要运行 10 次 dockerrun 命令呢？此外，如果容器之间有依赖顺序，你是不是还需要额外记住这 10 条命令特定的启动顺序？</p><p>K8s 的独特之处在于，它为我们抽象了诸如“启动 10 个容器镜像”这样的过程式的命令，你只需要向 K8s 描述“我需要 10 个容器”。10 个容器是我期望的最终状态，我不管怎么执行命令，执行了多少次命令等过程，我想要的就是这个结果。</p><p>用来向 K8s 描述“期望最终状态”的文件，就叫做 K8s Manifest，也可以称之为清单文件。Manifest 就好比餐厅的菜单，你只管点菜，做菜的过程我不管。</p><p>到这里，我们引出了第一个概念：Manifest。简单地说，它是用来描述如何将容器镜像部署到集群中的。Manifest 的概念非常重要，它会贯穿整个 K8s 的生态系统，所以请你务必要理解。</p><p>现在，假设我们有了一个 Manifest，我要如何告诉 K8s 呢？换句话说，我们怎么和 K8s 交流？这时候我们需要引入一个工具：Kubectl。</p><p>Kubectl 是一个与 K8s 集群交互的工具，通过 Kubectl，我们可以非常方便地以 Manifest 为媒介操作 K8s 集群的对象。就像操作数据库一样，我们可以对 Manifest 所描述的对象进行创建、删除、修改、查找等操作。</p><p>接下来，我们从编写 Manifest 开始，看看怎么将上节课制作的容器镜像部署到 K8s 集群中。</p><h3 id="部署容器镜像到-k8s" tabindex="-1">部署容器镜像到 K8s <a class="header-anchor" href="#部署容器镜像到-k8s" aria-label="Permalink to &quot;部署容器镜像到 K8s&quot;">​</a></h3><p>要将容器镜像部署到 K8s 集群中，我们首先需要书写 Manifest。我们需要将下面的内容保存为 flask-pod.yaml：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apiVersion: v1</span></span>
<span class="line"><span>kind: Pod</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span> name: hello-world-flask</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span> containers:</span></span>
<span class="line"><span>   - name: flask</span></span>
<span class="line"><span>     image: lyzhang1999/hello-world-flask:latest</span></span>
<span class="line"><span>     ports:</span></span>
<span class="line"><span>       - containerPort: 5000</span></span></code></pre></div><p>接下来，我们通过 kubectl apply 应用这段 Manifest：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl apply -f flask-pod.yaml</span></span>
<span class="line"><span>pod/hello-world-flask created</span></span></code></pre></div><p>需要注意的是，当使用 Kind 创建集群后，它会自动配置 Kubectl 和 Kind 集群的连接。如果连接配置不正确，你可以执行 kind export kubeconfig 来切换集群连接的上下文。</p><p>如果成功看到输出内容 pod/hello-world-flask created，说明我们已经把这段 Manifest 提交到集群里了。参数 -f 表示“指定一个 Manifest 文件”。</p><p>也就是说，当我们想要向 K8s 提交 Manifest 的时候，只需要记住一条命令，那就是 kubectlapply。</p><p>我们对上面的 Manifest 做一些必要的解释。其实这里只需要聚焦四个字段，分别是 Kind、Containers、Image、Ports。</p><p>Kind 字段表示 K8s 的工作负载类型。在 K8s 中，我们不能像 Docker 一样直接运行一个容器镜像，镜像需要依赖于 K8s 更上层的封装方式运行，这种封装方式也就是工作负载，Pod 是工作负载的一种类型。</p><p>每个工作负载有自己的名字，也就是 Metadata 节点下的 Name 字段。</p><p>为了更好地帮助你理解，我们可以把 Pod 类比成虚拟化技术中的 VM ，或者是 Docker 技术的容器，它们都是一种调度对象，如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/02-%25E5%25A6%2582%25E4%25BD%2595%25E5%25B0%2586%25E5%25AE%25B9%25E5%2599%25A8%25E9%2595%259C%25E5%2583%258F%25E9%2583%25A8%25E7%25BD%25B2%25E5%2588%25B0K8s%25EF%25BC%259F/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/02-%25E5%25A6%2582%25E4%25BD%2595%25E5%25B0%2586%25E5%25AE%25B9%25E5%2599%25A8%25E9%2595%259C%25E5%2583%258F%25E9%2583%25A8%25E7%25BD%25B2%25E5%2588%25B0K8s%25EF%25BC%259F/1.png" alt=""></a></p><p>在实际的项目中，我们一般不会直接创建 Pod 类型的工作负载，而是会通过其它的工作负载间接创建它们。如果你现在还不能理解 Pod 的概念也没关系，只需要记住它是 K8s 调度的最小单位就可以了。</p><p>Containers 字段代表 Pod 要运行的容器配置，例如名称、镜像和端口等。细心的你会注意到，它是一个数组类型，这意味着我们可以在一个 Pod 里面配置多个容器。</p><p>Image 字段表示容器镜像。显然，这里我们希望启动的是上节课制作的镜像，也就是lyzhang1999/hello-world-flask。需要注意将这里的 lyzhang1999 替换为你自己的 docker hub账户 ID。</p><p>Ports 字段表示容器要暴露的端口。它有点像我们在上节课提到的启动镜像时暴露的容器端口，也就是 docker run 的 p 参数。很显然我们希望暴露 5000 端口，也就是业务进程的监听端口。</p><p>接下来，我们继续回到实战环节。</p><p>当我们把 Manifest 部署到 K8s 集群之后，会面临两个问题：</p><ol><li><p>如何查看刚才提交的 Pod？</p></li><li><p>如何访问 Pod？</p></li></ol><h3 id="查看和访问-pod" tabindex="-1">查看和访问 Pod <a class="header-anchor" href="#查看和访问-pod" aria-label="Permalink to &quot;查看和访问 Pod&quot;">​</a></h3><p>先看第一个问题。要查看 K8s 集群正在运行中的 Pod，你可以使用 kubectl get pods ：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl get pods</span></span>
<span class="line"><span>NAME                READY   STATUS    RESTARTS   AGE</span></span>
<span class="line"><span>hello-world-flask   1/1     Running   0          1m</span></span></code></pre></div><p>可以看到，结果中返回了刚才部署名为 hello-world-flask 的 Pod，状态为“运行中”。还记得上节课我们提到怎么查看运行中容器的命令吗？是不是非常类似？</p><p>接下来我们尝试访问 Pod。要在本地访问集群内的 Pod，我们可以使用 kubectl port-forward命令进行端口转发操作，打通容器和本地网络：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl port-forward pod/hello-world-flask 8000:5000</span></span>
<span class="line"><span>Forwarding from 127.0.0.1:8000 -&gt; 5000</span></span>
<span class="line"><span>Forwarding from [::1]:8000 -&gt; 5000</span></span></code></pre></div><p>你可能会问，既然已经在 Manifest 里定义了 Ports 参数，为什么还需要进行端口转发操作呢？那是因为 Ports 参数只定义了 Pod 在集群内部暴露的端口，这个端口可以在集群内部进行访问。但我们本地和集群的网络是隔离的，自然不能在集群外部，也就是本地电脑访问Pod。</p><p>执行 kubectl port-forward 之后，我们打开浏览器访问 127.0.0.1:8000 就可以看到输出了：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hello, my first docker images! hello-world-flask</span></span></code></pre></div><p>需要注意的是，端口转发的进程是在前台运行的，你可以使用 ctrl+c 终止转发进程。</p><p>除了访问 Pod 以外，上节课我们还提到可以用 docker exec 进入运行中的容器。同样，我们也可以进入到 Pod 运行中的容器内。</p><p>你可以使用 kubectl exec 进入到 Pod 容器内部：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ kubectl exec -it hello-world-flask -- bash</span></span>
<span class="line"><span>root@hello-world-flask:/app#</span></span></code></pre></div><p>可以看到，这里的 -it 参数和 docker exec 的参数是完全一致的。在进入容器后，你可以试着像第一节课那样，修改 app.py 的输出，保存后刷新浏览器，观察一下是不是也能立即看到修改结果呢？</p><p>最后，我们可以通过 kubectl delete 命令来删除 Pod：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ kubectl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">delete</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pod hello</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">world</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flask</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pod </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;hello-world-flask&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> deleted</span></span></code></pre></div><p>到这里，我们就完成了将容器镜像部署到 K8s，还有查看、访问和删除 Pod 这一系列操作。</p><h3 id="业务进程、容器镜像和工作负载之间的关系" tabindex="-1">业务进程、容器镜像和工作负载之间的关系 <a class="header-anchor" href="#业务进程、容器镜像和工作负载之间的关系" aria-label="Permalink to &quot;业务进程、容器镜像和工作负载之间的关系&quot;">​</a></h3><p>通过上面的实战，我们将一个容器镜像以工作负载的方式部署到了 K8s 集群中。那么如果再往前追溯到业务层面，业务进程、容器镜像和工作负载之间的关系又是怎么样的呢？</p><p>当我初次接触 K8s 的时候，我对业务进程、容器镜像和工作负载层层封装，以及他们相互之间的关系感到非常疑惑。或许你也有同样的疑问，我为你总结了一张图，可以帮助你梳理一下它们之间的关系。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/02-%25E5%25A6%2582%25E4%25BD%2595%25E5%25B0%2586%25E5%25AE%25B9%25E5%2599%25A8%25E9%2595%259C%25E5%2583%258F%25E9%2583%25A8%25E7%25BD%25B2%25E5%2588%25B0K8s%25EF%25BC%259F/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E4%B8%8EGitOps%E5%AE%9E%E6%88%98/images/02-%25E5%25A6%2582%25E4%25BD%2595%25E5%25B0%2586%25E5%25AE%25B9%25E5%2599%25A8%25E9%2595%259C%25E5%2583%258F%25E9%2583%25A8%25E7%25BD%25B2%25E5%2588%25B0K8s%25EF%25BC%259F/2.png" alt=""></a></p><p>通过这张图可以看出，最内层是我们的业务应用进程，外层通过 Docker 镜像以容器化的形式运行，再往外是 K8s 的最小调度单位 Pod。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>这节课，我们通过 Kind 在本地创建了一个 K8s 集群。同时，在将容器镜像部署到 K8s 集群的过程中，我还给你介绍了 Manifest 以及 K8s 的最小调度单位 Pod 的概念。</p><p>此外，我们还介绍了与 K8s 集群交互的工具 Kubectl 及其简单操作，例如向集群提交Manifest、端口转发、查看、进入以及删除 Pod 等。</p><p>最后，我们还梳理了业务进程、镜像、容器和 Pod 之间的关系，理解它们将有助于你未来学习 K8s 的其他复杂概念。</p><p>到这里，你可能会问：学习了这么多概念，也花了这么多努力把容器镜像部署到了 K8s 集群，可是为什么还没看到 K8s 究竟能给我们带来什么实际的好处呢？</p><p>别着急，下节课，我会带你直观地感受 K8s 的魅力和强大之处：自动扩容和自愈。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>最后，给你留两道思考题吧。</p><ol><li><p>Kind 的全称是 Kubernetes in Docker，它的设计理念非常有意思。请你结合相关资料，说一说你对它的理解。</p></li><li><p>请你尝试为 hello-world-flask Pod 增加第二个容器，镜像为 nginx，端口为 80，并通过端口转发访问 Nginx Pod。</p></li></ol><p>欢迎你给我留言交流讨论，你也可以把这节课分享给更多的朋友。我们下节课见。</p>`,81)])])}const g=a(e,[["render",l]]);export{c as __pageData,g as default};
